export function toEventCborValue(v: Event): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("ref", toRecordRefCborValue(v.ref));
  csilMap.set("causes", v.causes.map((csilE): CborValue => toRecordRefCborValue(csilE)));
  csilMap.set("payload", toTypedPayloadCborValue(v.payload));
  csilMap.set("producer", toIdentityRefCborValue(v.producer));
  csilMap.set("event_type", v.eventType);
  csilMap.set("recipients", v.recipients.map((csilE): CborValue => toIdentityRefCborValue(csilE)));
  if (v.sessionId !== undefined) csilMap.set("session_id", v.sessionId);
  csilMap.set("occurred_at", { tag: 0, value: csilTsToText(v.occurredAt) });
  csilMap.set("recorded_at", { tag: 0, value: csilTsToText(v.recordedAt) });
  csilMap.set("restrictions", toRestrictionsCborValue(v.restrictions));
  return csilMap;
}

export function fromEventCborValue(value: CborValue): Event {
  return {
    ref: fromRecordRefCborValue(requireKey(value, "ref")),
    producer: fromIdentityRefCborValue(requireKey(value, "producer")),
    recipients: asArray(requireKey(value, "recipients")).map((csilE) => fromIdentityRefCborValue(csilE)),
    eventType: asString(requireKey(value, "event_type")),
    occurredAt: asTimestamp(requireKey(value, "occurred_at")),
    recordedAt: asTimestamp(requireKey(value, "recorded_at")),
    payload: fromTypedPayloadCborValue(requireKey(value, "payload")),
    causes: asArray(requireKey(value, "causes")).map((csilE) => fromRecordRefCborValue(csilE)),
    restrictions: fromRestrictionsCborValue(requireKey(value, "restrictions")),
    sessionId: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "session_id")),
  };
}

export function toEventCbor(v: Event): Uint8Array {
  return encodeValue(toEventCborValue(v));
}

export function fromEventCbor(bytes: Uint8Array): Event {
  return fromEventCborValue(decode(bytes));
}

